#!/usr/bin/env python3
"""Generate readonly candidate callees without changing ordinary/native CI."""

import argparse
import copy
import difflib
import re
from pathlib import Path

import yaml


ROOT = Path(__file__).resolve().parents[2]
SOURCES = {
    "v2-ci.yml": {
        "create-issue-on-failure",
        "nightly-release",
    },
    "v2-tests.yml": {
        "patch-coverage",
        "create-issue-on-failure",
        "create-issues-on-flakes",
        "warm-build-cache",
    },
    "go-security-analysis.yml": set(),
}
FLAG = "inputs.integration_candidate"
PROFILE_VARIABLES = {
    "vars.HIVE_GO_BUILD_CACHE": "'job'",
    "vars.HIVE_RUNNER_LABELS": "'[\"ubuntu-latest\"]'",
    "vars.HIVE_AFFECTED_TEST_SELECTION": "'false'",
}
HEADER = (
    "# Generated by .github/scripts/generate-integration-ci.py; do not edit.\n"
    "# Candidate-only technical CI. Ordinary and native CI remain in the source.\n"
)
CONTEXTS = {
    "build-and-test", "test", "coverage", "golangci-lint",
    "gosec (insecure patterns)", "govulncheck (known vulnerabilities)",
}
GOVERNANCE = {
    "dco": "DCO",
    "changelog": "changelog-fragment-guard",
    "contents": "verify PR contents",
    "attribution": "Sign-off survives the squash",
}


class WorkflowLoader(yaml.SafeLoader):
    pass


# GitHub's `on` is a string, not YAML 1.1's boolean spelling.
WorkflowLoader.yaml_implicit_resolvers = {
    key: [
        (tag, pattern)
        for tag, pattern in resolvers
        if tag != "tag:yaml.org,2002:bool"
    ]
    for key, resolvers in yaml.SafeLoader.yaml_implicit_resolvers.items()
}
WorkflowLoader.add_implicit_resolver(
    "tag:yaml.org,2002:bool", re.compile(r"^(?:true|false)$", re.I), list("tTfF")
)


class WorkflowDumper(yaml.SafeDumper):
    def ignore_aliases(self, _data):
        return True


def represent_string(dumper, value):
    return dumper.represent_scalar(
        "tag:yaml.org,2002:str", value, style="|" if "\n" in value else None
    )


WorkflowDumper.add_representer(str, represent_string)


def candidate_only(value):
    if isinstance(value, str):
        value = value.replace(FLAG, "true")
        value = re.sub(
            r"\bvars\.[A-Za-z0-9_]+",
            lambda match: PROFILE_VARIABLES.get(match.group(0), match.group(0)),
            value,
        )
        if re.search(r"\bvars\.", value) or re.search(r"\$\{\{[^}]*\bvars\b", value):
            raise ValueError("unqualified mutable workflow variable in candidate profile")
        return value
    if isinstance(value, list):
        return [candidate_only(item) for item in value]
    if isinstance(value, dict):
        return {key: candidate_only(item) for key, item in value.items()}
    return value


def render(source, document):
    if source not in SOURCES:
        raise ValueError(f"unsupported source {source}")
    document = copy.deepcopy(document)
    if set(document) != {
        "name", "on", "permissions", "concurrency", "env", "jobs"
    }:
        raise ValueError(f"{source}: source workflow structure needs review")
    candidate_input = (
        document["on"].get("workflow_call", {}).get("inputs", {}).get(
            "integration_candidate"
        )
    )
    if not isinstance(candidate_input, dict) or (
        candidate_input.get("type") != "boolean"
        or candidate_input.get("default") is not False
    ):
        raise ValueError(f"{source}: candidate entrypoint contract changed")
    if document["permissions"] != {"contents": "read"}:
        raise ValueError(f"{source}: readonly root permission contract changed")
    jobs = document["jobs"]
    for name in SOURCES[source]:
        if name not in jobs or f"!{FLAG}" not in str(jobs[name].get("if", "")):
            raise ValueError(f"{source}: excluded job {name} lost its guard")
        del jobs[name]
    for name, job in jobs.items():
        if any(value not in {"read", "none"} for value in job.get("permissions", {}).values()):
            raise ValueError(f"{source}: active job {name} requests write authority")
        runner = job.get("runs-on", "")
        if runner != "ubuntu-latest" and FLAG not in runner:
            raise ValueError(f"{source}: active job {name} lacks candidate runner isolation")
        job["runs-on"] = "ubuntu-latest"
        needs = job.get("needs", [])
        if isinstance(needs, str):
            needs = [needs]
        if any(dependency not in jobs for dependency in needs):
            raise ValueError(f"{source}: active job {name} depends on an excluded job")
        for step in job.get("steps", []):
            if str(step.get("uses", "")).startswith("actions/checkout@"):
                checkout = step.setdefault("with", {})
                if "ref" in checkout:
                    raise ValueError(f"{source}: active job {name} overrides the tested subject")
                checkout["persist-credentials"] = False
    document["name"] = f"Integration candidate / {document['name']}"
    document["on"] = {"workflow_call": None}
    document["concurrency"]["cancel-in-progress"] = False
    document = candidate_only(document)
    return HEADER + yaml.dump(
        document, Dumper=WorkflowDumper, sort_keys=False, width=10000
    )

def compose(documents):
    template = ROOT / ".github" / "integration-candidate.template.yml"
    entry = yaml.load(template.read_text(), Loader=WorkflowLoader)
    jobs = entry["jobs"]
    receipt = jobs.pop("receipt")
    bindings = {"gate": "subject"}
    for source, document in documents.items():
        lane = {"v2-ci.yml": "ci", "v2-tests.yml": "tests",
                "go-security-analysis.yml": "security"}[source]
        generated = yaml.load(render(source, document), Loader=WorkflowLoader)
        mapping = {key: f"{lane}-{key}" for key in generated["jobs"]}

        def rewrite(value):
            if isinstance(value, str):
                return re.sub(r"\bneeds\.([A-Za-z0-9_-]+)",
                              lambda match: "needs." + mapping.get(match[1], match[1]), value)
            if isinstance(value, list):
                return [rewrite(item) for item in value]
            if isinstance(value, dict):
                return {key: rewrite(item) for key, item in value.items()}
            return value

        for key, original in generated["jobs"].items():
            job = rewrite(original)
            dependencies = original.get("needs", [])
            if isinstance(dependencies, str):
                dependencies = [dependencies]
            job["needs"] = ["subject"] + [mapping[value] for value in dependencies]
            condition = str(job.get("if", "${{ success() }}")).strip()
            if condition.startswith("${{") and condition.endswith("}}"):
                condition = condition[3:-2].strip()
            job["if"] = "${{ always() && needs.subject.result == 'success' && (" + condition + ") }}"
            job["name"] = original.get("name", key)
            job["env"] = {**generated.get("env", {}), **job.get("env", {})}
            if job["name"] in CONTEXTS:
                if job["name"] in bindings:
                    raise ValueError(f"duplicate required context {job['name']}")
                bindings[job["name"]] = mapping[key]
            if source == "v2-tests.yml" and key == "test":
                for step in job["steps"]:
                    if step.get("name") == "Check shard results":
                        step["run"] = step["run"].replace(
                            'if [ "${#cancelled[@]}" -gt 0 ]; then',
                            'if [ "${#cancelled[@]}" -gt 0 ]; then\n  echo "::error::Candidate shards must all complete"; exit 1')
            jobs[mapping[key]] = job
    if set(bindings) != CONTEXTS | {"gate"}:
        raise ValueError("actual technical producer context coverage changed")
    for kind, name in GOVERNANCE.items():
        key = f"governance-{kind}"
        bindings[name] = key
        jobs[key] = {
            "name": name, "needs": ["subject"], "runs-on": "ubuntu-latest",
            "timeout-minutes": 15,
            "outputs": {"metadata_digest": "${{ steps.verify.outputs.metadata_digest }}"},
            "steps": [
                {"uses": "actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1",
                 "with": {"fetch-depth": 0, "persist-credentials": False}},
                {"name": "Verify exact current members with trusted readonly policy", "id": "verify",
                 "uses": "actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3",
                 "env": {"SUBJECT_MANIFEST": "${{ inputs.manifest }}",
                         "EXPECTED_METADATA_DIGEST": "${{ needs.subject.outputs.metadata_digest }}",
                         "GITHUB_TOKEN": "${{ github.token }}"},
                 "with": {"script": (
                     "const policy = require('./.github/scripts/integration-governance.cjs');\n"
                     "const subject = JSON.parse(process.env.SUBJECT_MANIFEST);\n"
                     "const members = await policy.snapshot(github, subject);\n"
                     "const actual = policy.digest(members);\n"
                     "if (actual !== process.env.EXPECTED_METADATA_DIGEST) throw new Error('Member metadata drifted');\n"
                     "core.setOutput('metadata_digest', actual);\n"
                     f"await policy.verify('{kind}', subject, members, github);\n"
                 )}},
            ],
        }
    receipt["needs"] = list(jobs)
    for step in receipt["steps"]:
        if "REQUIRED_CONTEXT_JOBS" in step.get("env", {}):
            import json
            step["env"]["REQUIRED_CONTEXT_JOBS"] = json.dumps(bindings, sort_keys=True)
    jobs["receipt"] = receipt
    return HEADER + yaml.dump(entry, Dumper=WorkflowDumper, sort_keys=False, width=10000)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    different = False
    documents = {}
    for source in SOURCES:
        original = ROOT / ".github" / "workflows" / source
        output = original.with_name(f"integration-technical-{source}")
        documents[source] = yaml.load(original.read_text(), Loader=WorkflowLoader)
        expected = render(source, documents[source])
        if args.check:
            actual = output.read_text() if output.exists() else ""
            if actual != expected:
                different = True
                print("".join(difflib.unified_diff(
                    actual.splitlines(True), expected.splitlines(True),
                    fromfile=str(output), tofile=f"{output} (generated)"
                )))
        else:
            output.write_text(expected)
            print(output.relative_to(ROOT))
    output = ROOT / ".github" / "workflows" / "integration-candidate.yml"
    expected = compose(documents)
    if args.check:
        if not output.exists() or output.read_text() != expected:
            different = True
            print("integration-candidate.yml differs from its trusted template/composed producers")
    else:
        output.write_text(expected)
        print(output.relative_to(ROOT))
    if different:
        raise SystemExit("Run python3 .github/scripts/generate-integration-ci.py")


if __name__ == "__main__":
    main()
